SELECT COUNT(1) FROM stock_daily_bar
WHERE trade_date >= #{startDate} AND trade_date <= #{endDate}
  AND (adjust_type != #{expectedAdjustType} OR data_source != #{expectedDataSource})

    AND canonical_symbol IN
    #{symbol}

